export const BOA_SKILLS={pistolkiss:{cooldown:6,cast:.3,duration:.8},slavearrow:{cooldown:10,cast:.6,duration:1.15},perfumefemur:{cooldown:8,cast:.35,duration:.9},meromellow:{cooldown:14,cast:.65,duration:1.15}};
export const boa_hancock={name:'Boa Hancock',rangedBasic:true,assets:['boa_hancock','boa_hancock_vfx','boa_hancock_intro','boa_hancock_intro_vfx','boa_hancock_ultimate_vfx','boa_hancock_dialogue'],stats:{hp:1050,speed:215,melee:65,skillPower:100,cooldown:100,aggression:45,preferredRange:240},
 init(f){f.rage=0;f.rageLockUntil=0;f.rageReadyTick=null;f.personalUses=0;f.heartshotCd=.5*f.cooldownFactor;f.skillUses.heartshot=0;for(const [k,v] of Object.entries({pistolkiss:1,slavearrow:3,perfumefemur:2,meromellow:5})){f[k+'Cd']=v*f.cooldownFactor;f.skillUses[k]=0;}},
 onAct(f,s,d){if(s==='heartshot'){f.heartshotCd=.95*f.cooldownFactor;f.skillUses.heartshot++;}else if(BOA_SKILLS[s]){f[s+'Cd']=BOA_SKILLS[s].cooldown*f.cooldownFactor;f.skillUses[s]++;}else return;f.boaTarget=d.pickTarget(f)?.uid;},
 tick(f,dt){for(const k of [...Object.keys(BOA_SKILLS),'heartshot'])f[k+'Cd']=Math.max(0,f[k+'Cd']-dt);},
 preferredApproachRange(f){return Math.max(130,f.preferredRange*.75);},
 danger(d,t){return d.fighters.some(f=>{if(f.id!=='boa_hancock'||f.hp<=0||!d.isEnemy(f,t))return false;const dx=t.x-f.x,dy=t.y-f.y,n=Math.hypot(dx,dy)||1;return f.state==='perfumefemur'&&f.age>.1&&f.age<.4&&n<190||f.state==='meromellow'&&f.age>.15&&f.age<.7&&n<390&&(dx*f.actionX+dy*f.actionY)/n>.65;});},
 updateAction(d,f,o,hits,dx,dy,dist,dt){const s=f.state,spec=BOA_SKILLS[s]||(s==='heartshot'?{cast:.18,duration:.48}:null);if(!spec)return false;const t=d.fighters.find(t=>t.uid===f.boaTarget&&t.hp>0&&d.isEnemy(f,t))||o;
  if(s==='perfumefemur'&&f.age<.25&&d.tick>=(f.rootUntil||0)){const tx=t.x-f.x,ty=t.y-f.y,n=Math.hypot(tx,ty)||1,move=Math.min(Math.max(0,n-75),400*dt);f.x+=tx/n*move;f.y+=ty/n*move;d.clampPosition(f);}
  if(f.age>=spec.cast&&!f.hit){f.hit=true;if(s==='perfumefemur'||s==='meromellow'){const range=s==='perfumefemur'?135:370,dot=s==='perfumefemur'?.25:.7;for(const target of d.fighters){const tx=target.x-f.x,ty=target.y-f.y,n=Math.hypot(tx,ty)||1;if(target.hp>0&&d.isEnemy(f,target)&&n<range&&(tx*f.actionX+ty*f.actionY)/n>dot)hits.push({source:f,target,value:s==='perfumefemur'?150:100,slowTicks:s==='perfumefemur'?90:0,petrifyTicks:s==='meromellow'?42:0,knockback:s==='perfumefemur'?30:0});}d.event(s==='perfumefemur'?'boaKick':'boaWave',f,{x:f.x+f.actionX*85,y:f.y+f.actionY*85});}
   else {const tx=t.x-f.x,ty=t.y-f.y,n=Math.hypot(tx,ty)||1,angles=s==='slavearrow'?[-.16,-.08,0,.08,.16]:[0];for(const angle of angles){const c=Math.cos(angle),sn=Math.sin(angle),ux=tx/n*c-ty/n*sn,uy=tx/n*sn+ty/n*c,kind=s==='slavearrow'?'heartarrow':'heartbolt';d.shots.push({id:f.id,ownerUid:f.uid,kind,skill:s,damage:s==='heartshot'?f.melee:s==='pistolkiss'?150:45,damageKind:s==='heartshot'?'melee':undefined,radius:s==='slavearrow'?18:24,x:f.x+ux*32,y:f.y+uy*32,vx:ux*650,vy:uy*650,life:1.1,piercing:s==='slavearrow',hitUids:[],impactEvent:'boaImpact'});}d.event('fire',f,{skill:s});}}
  if(f.age>=spec.duration){f.state='idle';f.age=0;}return true;
 },
 chooseBasic(d,f,o,dx,dy,dist){if(f.heartshotCd===0&&dist<600){d.act(f,'heartshot',dx,dy);return true;}return false;},
 chooseSkill(d,f,o,dx,dy,dist){for(const k of ['perfumefemur','meromellow','slavearrow','pistolkiss'])if(f[k+'Cd']===0&&(k==='perfumefemur'?dist<220:k==='meromellow'?dist<370:k==='slavearrow'?dist>150&&dist<620:dist<600)){d.act(f,k,dx,dy);return true;}return false;}
};
export function boaPose(f,hurt=false){if(f.introAge!=null){const a=f.introAge;if(a<.9)return {row:0,frame:Math.min(5,Math.floor(a/.9*6))};if(a<1.85)return {row:1,frame:Math.min(5,Math.floor((a-.9)/.95*6))};return {row:2,frame:Math.min(5,Math.floor((a-1.85)/.65*6))};}const s=hurt?'hurt':f.state,spec=BOA_SKILLS[s]||(s==='heartshot'?{duration:.48}:null);return {row:({idle:0,run:1,melee:3,heartshot:2,dash:4,guard:5,hurt:5,defeat:6,pistolkiss:7,slavearrow:8,perfumefemur:9,meromellow:10})[s]??0,frame:spec?Math.min(5,Math.floor(f.age/spec.duration*6)):['defeat','hurt','melee','dash','guard'].includes(s)?Math.min(5,Math.floor(f.age*10)):Math.floor(f.age*9)%6};}
